import io
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_receipt_fields(payload, config=None):
    config = config or {}
    with DocumentIntelligenceClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.begin_analyze_document('prebuilt-receipt',
            body=io.BytesIO(payload['document_bytes']), content_type=payload['mime_type']).result()
    receipts = []
    for document in result.documents or []:
        fields = document.fields or {}
        text = lambda values, key: values[key].content if key in values else None
        items = fields.get('Items')
        lines = []
        for item in (items.value_array or []) if items else []:
            values = item.value_object or {}
            lines.append({'description': text(values, 'Description'), 'quantity': text(values, 'Quantity'), 'price': text(values, 'Price'), 'total': text(values, 'Total')})
        receipts.append({'merchant': text(fields, 'MerchantName'), 'tax': text(fields, 'Tax'), 'total': text(fields, 'Total'), 'items': lines})
    return {'receipts': receipts}

import json


def normalize_expense(expense):
    normalized_expense = {
        'vendor': expense.get('vendor', ''),
        'date': expense.get('date', ''),
        'total': expense.get('total', ''),
        'line_items': []
    }
    for item in expense.get('line_items', []):
        normalized_item = {
            'description': item.get('description', ''),
            'quantity': item.get('quantity', ''),
            'amount': item.get('amount', '')
        }
        normalized_expense['line_items'].append(normalized_item)
    return json.dumps(normalized_expense, indent=2)

def validate_document_fields(document):
    required_fields = ['vendor', 'date', 'total']
    for field in required_fields:
        if field not in document:
            raise ValueError(f'Missing required field: {field}')
    if 'line_items' not in document or not document['line_items']:
        raise ValueError('Missing line items')
    for item in document['line_items']:
        if 'description' not in item or 'quantity' not in item or 'amount' not in item:
            raise ValueError('Missing required fields in line item')

import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def get_document_client():
    return DocumentIntelligenceClient(os.getenv('DOCUMENT_INTELLIGENCE_ENDPOINT'), AzureKeyCredential(os.getenv('DOCUMENT_INTELLIGENCE_API_KEY')))

def normalize_document_response(response):
    normalized_response = {
        'document_type': response.get('document_type', ''),
        'fields': {}
    }
    for field, value in response.get('fields', {}).items():
        normalized_response['fields'][field] = value.content
    return normalized_response

import os
import requests


def moderate_vendor_text(text):
    response = requests.post(os.getenv('TEXT_MODERATION_ENDPOINT'), json={'text': text})
    if response.status_code!= 200:
        raise Exception('Text moderation service error')
    result = response.json()
    if result.get('flagged'):
        raise ValueError('Vendor text contains inappropriate content')

import os
import requests


def translate_invoice_note(text, target_language='en'):
    response = requests.post(os.getenv('TRANSLATION_ENDPOINT'), json={'text': text, 'target_language': target_language})
    if response.status_code!= 200:
        raise Exception('Translation service error')
    result = response.json()
    return result.get('translated_text', '')

